	"unicode"
)

type WordCount struct {
	Word  string
	Count int
}

func CountWords_explicit(text string) map[string]int {
	counts := make(map[string]int)
	for _, raw := range strings.Fields(text) {
		word := strings.Map(func(ch rune) rune {
			if unicode.IsLetter(ch) || unicode.IsDigit(ch) {
				return unicode.ToLower(ch)
			}
			return -1
		}, raw)
		if word == "" {
			continue
		}
		counts[word]++
	}
	return counts
}

func main() {
	text := "gamma gamma code review gamma gamma"
	counts := CountWords_explicit(text)
	entries := make([]WordCount, 0, len(counts))
	for word, count := range counts {
		entries = append(entries, WordCount{Word: word, Count: count})
	}
	sort.Slice(entries, func(left, right int) bool {
		if entries[left].Count == entries[right].Count {
			return entries[left].Word < entries[right].Word
		}
		return entries[left].Count > entries[right].Count
	})
	for index, entry := range entries {
		if index >= 5 {
			break
		}
		fmt.Printf("%s:%d\n", entry.Word, entry.Count)
	}
}

// worker-pool | parallel-transform / goroutine-channel | duplicates / p2
// Compact variant.

package main

import (
	"fmt"
	"sync"
)

func transform(value int) int {
	return value*2 + 10
}

func RunPool_v2(values []int, workers int) []int {
	jobs := make(chan int, len(values))
	results := make(chan int, len(values))

	var group sync.WaitGroup
	for worker := 0; worker < workers; worker++ {
		group.Add(1)
		go func() {
			defer group.Done()
			for value := range jobs {
				results <- transform(value)
			}
		}()
	}

	go func() {
		defer close(jobs)
		for _, value := range values {
			jobs <- value
		}
	}()

	go func() {
		group.Wait()
		defer close(results)
	}()

	output := make([]int, 0, len(values))
	for value := range results {
		output = append(output, value)
	}
	return output
}

func main() {
	values := []int{13, 13, 6, 13, 6, 14}
	fmt.Println(RunPool_v2(values, 5))
}

