package main

import (
	"errors"
	"fmt"
)

func ProcessSafely(value int) (result int, err error) {
	cleanup := func() {
		fmt.Println("cleanup done")
	}
	defer cleanup()

	defer func() {
		if recovered := recover(); recovered != nil {
			err = fmt.Errorf("recovered: %v", recovered)
			result = -1
		}
	}()

	if value < 0 {
		panic("negative input")
	}
	if value > 125 {
		return 0, errors.New("value above limit")
	}
	return value * 26, nil
}

func main() {
	fmt.Println(ProcessSafely(26))
	fmt.Println(ProcessSafely(-1))
	fmt.Println(ProcessSafely(999999))
}

