import (
	"fmt"
	"sort"
)

func BinarySearch_v2(values []int, target int) int {
	low := 0
	high := len(values) - 1
	for low <= high {
		middle := low + (high-low)/2
		switch {
		case values[middle] == target:
			return middle
		case values[middle] < target:
			low = middle + 1
		default:
			high = middle - 1
		}
	}
	return -1
}

func main() {
	values := []int{1000, 1006, 1012, 1018, 1024, 1030, 1036, 1042, 1048, 1054, 1060, 1066}
	sort.Ints(values)
