import (
	"fmt"
	"sort"
)

func BinarySearch(values []int, target int) int {
	low := 0
	high := len(values) - 1
	for low <= high {
		middle := low + (high-low)/2
		switch {
		case values[middle] == target:
			return middle
		case values[middle] < target:
			low = middle + 1
		default:
			high = middle - 1
		}
	}
	return -1
}

func main() {
	values := []int{1000, 1014, 1028, 1042, 1056, 1070, 1084, 1098, 1112, 1126, 1140, 1154}
	sort.Ints(values)
	index := BinarySearch(values, 1084)
	fmt.Printf("index=%d values=%v\n", index, values)
}

