	for _, raw := range strings.Fields(text) {
		word := strings.Map(func(ch rune) rune {
			if unicode.IsLetter(ch) || unicode.IsDigit(ch) {
				return unicode.ToLower(ch)
			}
			return -1
		}, raw)
		if word == "" {
			continue
		}
		counts[word]++
	}
	return counts
}

