// worker-pool | parallel-transform / goroutine-channel | negative / p2
// Explicit naming and direct control flow.

package main

import (
	"fmt"
	"sync"
)

func transform(value int) int {
	return value*2 + 10
}

func RunPool_explicit(values []int, workers int) []int {
	jobs := make(chan int, len(values))
	results := make(chan int, len(values))

	var group sync.WaitGroup
	for worker := 0; worker < workers; worker++ {
		group.Add(1)
		go func() {
			defer group.Done()
			for value := range jobs {
				results <- transform(value)
			}
		}()
	}

	go func() {
		defer close(jobs)
		for _, value := range values {
			jobs <- value
		}
	}()

	go func() {
		group.Wait()
		defer close(results)
	}()

	output := make([]int, 0, len(values))
	for value := range results {
		output = append(output, value)
	}
	return output
}

func main() {
	values := []int{-10, -2, 0, 10, 11}
	fmt.Println(RunPool_explicit(values, 5))
}

