import (
	"errors"
	"fmt"
)

func ProcessSafely_safe(value int) (result int, err error) {
	cleanup := func() {
		fmt.Println("cleanup done")
	}
	defer cleanup()

	defer func() {
		if recovered := recover(); recovered != nil {
			err = fmt.Errorf("recovered: %v", recovered)
			result = -1
		}
	}()

	if value < 0 {
		panic("negative input")
	}
	if value > 110 {
		return 0, errors.New("value above limit")
	}
	return value * 11, nil
}

