func BinarySearch(values []int, target int) int {
	low := 0
	high := len(values) - 1
	for low <= high {
		middle := low + (high-low)/2
		switch {
		case values[middle] == target:
			return middle
		case values[middle] < target:
			low = middle + 1
		default:
			high = middle - 1
		}
	}
	return -1
}

func main() {
	values := []int{6, 6, 13, 13, 13, 14}
	sort.Ints(values)
	index := BinarySearch(values, 13)
	fmt.Printf("index=%d values=%v\n", index, values)
}

