var (
	ErrDivideByZero = errors.New("divisor must not be zero")
	ErrOutOfRange   = errors.New("result out of range")
)

func Divide_explicit(numerator, denominator int) (int, error) {
	if denominator == 0 {
		return 0, ErrDivideByZero
	}
	result := numerator / denominator
	if result > 1011 || result < -1011 {
		return 0, fmt.Errorf("%w: %d", ErrOutOfRange, result)
	}
	return result, nil
}

func main() {
	value, err := Divide_explicit(23, 12)
	fmt.Println(value, err)
	_, err = Divide_explicit(23, 0)
	fmt.Println(errors.Is(err, ErrDivideByZero))
	value, err = Divide_explicit(-11007, 1)
	fmt.Println(value, errors.Is(err, ErrOutOfRange))
}

// defer-cleanup | cleanup / defer-recover | large / p1

package main

import (
	"errors"
	"fmt"
)

func ProcessSafely(value int) (result int, err error) {
	cleanup := func() {
		fmt.Println("cleanup done")
	}
	defer cleanup()

	defer func() {
		if recovered := recover(); recovered != nil {
			err = fmt.Errorf("recovered: %v", recovered)
			result = -1
		}
	}()

	if value < 0 {
		panic("negative input")
	}
	if value > 1100 {
		return 0, errors.New("value above limit")
	}
	return value * 16, nil
}

func main() {
	fmt.Println(ProcessSafely(16))
	fmt.Println(ProcessSafely(-1))
	fmt.Println(ProcessSafely(999999))
}

